sql:
SELECT o.id,typeof(o.k) FROM outer_values o
    WHERE o.k IN (SELECT i.k FROM inner_values i WHERE i.grp=o.grp)
    ORDER BY o.id;

SELECT o.id,typeof(o.k) FROM outer_values o
    WHERE o.k IN (SELECT i.k COLLATE NOCASE FROM inner_values i WHERE i.grp=o.grp)
    ORDER BY o.id;

SELECT o.id,typeof(o.k) FROM outer_values o
    WHERE o.k||'' IN (SELECT i.k FROM inner_values i WHERE i.grp=o.grp)
    ORDER BY o.id;
